probes.source:
//@version=5
indicator("probe", overlay=true)
plotarrow(close - open, "Move", colorup=color.green, colordown=color.red)

//@version=5
indicator("probe")
plotbar(open, high, low, close, "Bars", color=close > open ? color.green : color.red)

//@version=5
indicator("probe", overlay=true)
n = input.int(5, "Bars each side")
ph = ta.pivothigh(high, n, n)
if not na(ph)
    box.new(bar_index - n, ph, bar_index, ph - ta.atr(14), extend=extend.right, bgcolor=color.new(color.red, 85), border_color=color.red)

//@version=5
indicator("probe", overlay=true)
var float[] sums = array.new_float(7, 0.0)
var int[] counts = array.new_int(7, 0)
r = close / close[1] - 1
if not na(r)
    array.set(sums, dayofweek - 1, array.get(sums, dayofweek - 1) + r)
    array.set(counts, dayofweek - 1, array.get(counts, dayofweek - 1) + 1)
var table t = table.new(position.top_right, 2, 7)
if barstate.islast
    for d = 0 to 6
        table.cell(t, 0, d, str.tostring(d + 1))
        table.cell(t, 1, d, array.get(counts, d) > 0 ? str.tostring(array.get(sums, d) / array.get(counts, d) * 100, "#.##") + "%" : "-")

//@version=5
indicator("probe", overlay=true)
var map<string, float> m = map.new<string, float>()
map.put(m, "c", close)
plot(map.get(m, "c"), "c")
